mapper.select:
SELECT * FROM conversation 
WHERE user_id = #{userId} 
  AND target_id = #{targetId} 
  AND conversation_type = #{conversationType}
LIMIT 1

SELECT COALESCE(SUM(unread_count), 0) 
FROM conversation 
WHERE user_id = #{userId}

SELECT COALESCE(unread_count, 0) 
FROM conversation 
WHERE conversation_id = #{conversationId} 
  AND user_id = #{userId}

mapper.update:
UPDATE conversation 
SET unread_count = unread_count + #{delta},
    updated_at = NOW()
WHERE conversation_id = #{conversationId} 
  AND user_id = #{userId}

UPDATE conversation 
SET unread_count = 0,
    updated_at = NOW()
WHERE conversation_id = #{conversationId} 
  AND user_id = #{userId}

UPDATE conversation 
SET is_pinned = #{isPinned},
    updated_at = NOW()
WHERE conversation_id = #{conversationId} 
  AND user_id = #{userId}

mapper.delete:
DELETE FROM conversation 
WHERE conversation_id = #{conversationId} 
  AND user_id = #{userId}

